={{ JSON.stringify({
  contents: [{ role: 'user', parts: [{ text: 'Você é analista de qualidade de um app de delivery de comida. Classifique a avaliação abaixo.\n\nCategorias possíveis: atraso, pedido_errado_ou_incompleto, qualidade_da_comida, seguranca_alimentar, cobranca, entregador, embalagem, preco_ou_porcao, elogio, outro.\nUrgência: alta = risco à saúde, cobrança indevida, pedido errado ou faltando com nota até 2, ou entregador desrespeitoso; media = problema real sem risco; baixa = elogio ou detalhe.\nresposta_sugerida: resposta do restaurante ao cliente, empática, em português, no máximo 2 frases, sem prometer o que não pode cumprir.\nacao_interna: o que o restaurante deve corrigir na operação, em 1 frase.\noferecer_cupom: true só se houve falha do restaurante ou da entrega.\n\nRestaurante: ' + $json.restaurante + '\nNota: ' + $json.nota + ' de 5\nComentário: ' + $json.comentario }] }],
  generationConfig: {
    temperature: 0.2,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        categoria: { type: 'STRING', enum: ['atraso','pedido_errado_ou_incompleto','qualidade_da_comida','seguranca_alimentar','cobranca','entregador','embalagem','preco_ou_porcao','elogio','outro'] },
        sentimento: { type: 'STRING', enum: ['positivo','neutro','negativo'] },
        urgencia: { type: 'STRING', enum: ['alta','media','baixa'] },
        resumo: { type: 'STRING' },
        resposta_sugerida: { type: 'STRING' },
        acao_interna: { type: 'STRING' },
        oferecer_cupom: { type: 'BOOLEAN' }
      },
      required: ['categoria','sentimento','urgencia','resumo','resposta_sugerida','acao_interna','oferecer_cupom']
    }
  }
}) }}

