const entrada = $('Normalizar').item.json;
const texto = $json.candidates?.[0]?.content?.parts?.map(p => p.text || '').join('') || '{}';
let ia;
try { ia = JSON.parse(texto); } catch (e) { ia = { categoria: 'outro', sentimento: 'neutro', urgencia: 'media', resumo: 'Falha ao ler resposta da IA', resposta_sugerida: '', acao_interna: 'Revisar manualmente', oferecer_cupom: false }; }
const registro = {
  id: entrada.recebida_em.toString(36) + Math.random().toString(36).slice(2, 6),
  ...entrada,
  ...ia,
  triagem_ms: Date.now() - entrada.recebida_em
};
const banco = $getWorkflowStaticData('global');
banco.avaliacoes = banco.avaliacoes || [];
banco.avaliacoes.unshift(registro);
banco.avaliacoes = banco.avaliacoes.slice(0, 500);
return registro;

const banco = $getWorkflowStaticData('global');
banco.avaliacoes = [];
return [{ json: { ok: true } }];
